<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Double Pendulum — RK4</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    overflow: hidden;
    background: #0b0e17;
  }
  canvas {
    display: block;
    width: 100vw;
    height: 100vh;
    cursor: pointer;
  }
  #hint {
    position: fixed;
    left: 12px;
    bottom: 10px;
    color: rgba(160, 175, 210, 0.55);
    font: 12px/1.4 system-ui, sans-serif;
    user-select: none;
    pointer-events: none;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hint">double pendulum · RK4 · click to randomize</div>
<script>
"use strict";

/* ================= Canvas setup (HiDPI aware) ================= */
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
let W = 0, H = 0;

function resize() {
  const dpr = window.devicePixelRatio || 1;
  W = window.innerWidth;
  H = window.innerHeight;
  canvas.width  = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  renderScale = Math.min(W, H) * 0.36 / (L1 + L2); // px per meter
  trail.length = 0; // old trail points are stale after resize
}

/* ================= Physical parameters (SI units) ================= */
const g  = 9.81;          // gravitational acceleration (m/s^2)
const L1 = 0.55, L2 = 0.45; // rod lengths (m)
const m1 = 1.0,  m2 = 1.0;  // bob masses (kg)
let renderScale = 1;        // px per meter (set in resize)

function pivot() { return { x: W * 0.5, y: H * 0.42 }; }

/* ============ State vector: [theta1, omega1, theta2, omega2] ============
   Angles measured from the downward vertical, CCW positive.              */
let state = [Math.PI * 0.78, 0, Math.PI * 0.92, 0];

/* ======== Equations of motion derived from the Lagrangian ========
   L = 1/2 (m1+m2) L1^2 w1^2 + 1/2 m2 L2^2 w2^2
       + m2 L1 L2 w1 w2 cos(th1-th2)
       + (m1+m2) g L1 cos(th1) + m2 g L2 cos(th2)

   Euler–Lagrange gives, with d = th1 - th2 and M = m1 + m2:

     M L1 a1 + m2 L2 cos(d) a2 = -m2 L2 w2^2 sin(d) - M g sin(th1)
     L1 cos(d) a1 + L2 a2      =  L1 w1^2 sin(d) - g sin(th2)

   Solving this 2x2 linear system for (a1, a2):
=================================================================== */
function derivatives(s, out) {
  const th1 = s[0], w1 = s[1], th2 = s[2], w2 = s[3];
  const d  = th1 - th2;
  const M  = m1 + m2;
  const sd = Math.sin(d), cd = Math.cos(d);
  const den = M - m2 * cd * cd;              // = m1 + m2 sin^2(d) > 0

  const a1 = (-m2 * L2 * w2 * w2 * sd - M * g * Math.sin(th1)
              - m2 * cd * (L1 * w1 * w1 * sd - g * Math.sin(th2))) / (L1 * den);

  const a2 = (M * (L1 * w1 * w1 * sd - g * Math.sin(th2))
              + cd * (m2 * L2 * w2 * w2 * sd + M * g * Math.sin(th1))) / (L2 * den);

  out[0] = w1; out[1] = a1; out[2] = w2; out[3] = a2;
  return out;
}

/* ================= Classical 4th-order Runge–Kutta ================= */
const k1 = [0,0,0,0], k2 = [0,0,0,0], k3 = [0,0,0,0], k4 = [0,0,0,0], tmp = [0,0,0,0];

function rk4(s, dt) {
  derivatives(s, k1);
  for (let i = 0; i < 4; i++) tmp[i] = s[i] + 0.5 * dt * k1[i];
  derivatives(tmp, k2);
  for (let i = 0; i < 4; i++) tmp[i] = s[i] + 0.5 * dt * k2[i];
  derivatives(tmp, k3);
  for (let i = 0; i < 4; i++) tmp[i] = s[i] + dt * k3[i];
  derivatives(tmp, k4);
  for (let i = 0; i < 4; i++)
    s[i] += (dt / 6) * (k1[i] + 2 * k2[i] + 2 * k3[i] + k4[i]);
}

/* ================= Forward kinematics (pixels) ================= */
function positions(s) {
  const p = pivot();
  const x1 = p.x + renderScale * L1 * Math.sin(s[0]);
  const y1 = p.y + renderScale * L1 * Math.cos(s[0]);
  const x2 = x1 + renderScale * L2 * Math.sin(s[2]);
  const y2 = y1 + renderScale * L2 * Math.cos(s[2]);
  return { p, x1, y1, x2, y2 };
}

/* ================= Motion trail ================= */
const TRAIL_MAX = 700;
const trail = [];          // {x, y} positions of the second bob

function drawTrail() {
  const n = trail.length;
  if (n < 2) return;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (let i = 1; i < n; i++) {
    const t = i / n;                       // 0 = oldest, 1 = newest
    const hue = 185 + 125 * t;             // cyan -> magenta drift
    ctx.strokeStyle = `hsla(${hue}, 90%, ${45 + 20 * t}%, ${0.02 + 0.5 * t * t})`;
    ctx.lineWidth = 0.5 + 2.5 * t;
    ctx.beginPath();
    ctx.moveTo(trail[i - 1].x, trail[i - 1].y);
    ctx.lineTo(trail[i].x, trail[i].y);
    ctx.stroke();
  }
}

/* ================= Pendulum rendering ================= */
function drawBob(x, y, r, color) {
  const grad = ctx.createRadialGradient(x, y, 0, x, y, r * 2.4);
  grad.addColorStop(0, color);
  grad.addColorStop(0.4, color);
  grad.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x, y, r * 2.4, 0, Math.PI * 2);
  ctx.fill();
}

function drawPendulum(pos) {
  const { p, x1, y1, x2, y2 } = pos;

  // arms
  ctx.lineCap = "round";
  ctx.strokeStyle = "rgba(220, 228, 255, 0.85)";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();

  // pivot
  ctx.fillStyle = "#8892b0";
  ctx.beginPath();
  ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
  ctx.fill();

  // bobs (radius scales with cube root of mass)
  drawBob(x1, y1, 8 + 6 * Math.cbrt(m1), "#ffd166");
  drawBob(x2, y2, 8 + 6 * Math.cbrt(m2), "#4cc9f0");
}

/* ============ Main loop: fixed-timestep physics, accumulator ============ */
const DT = 1 / 240;        // physics step (s)
let last = performance.now();
let acc = 0;

function frame(now) {
  let elapsed = (now - last) / 1000;
  last = now;
  if (elapsed > 0.1) elapsed = 0.1;   // clamp after tab switch
  acc += elapsed;

  while (acc >= DT) {
    rk4(state, DT);
    acc -= DT;
    const pos = positions(state);
    trail.push({ x: pos.x2, y: pos.y2 });
    if (trail.length > TRAIL_MAX) trail.shift();
  }

  ctx.fillStyle = "#0b0e17";
  ctx.fillRect(0, 0, W, H);

  drawTrail();
  drawPendulum(positions(state));

  requestAnimationFrame(frame);
}

/* ================= Interaction & housekeeping ================= */
canvas.addEventListener("pointerdown", () => {
  // Restart from a random high-energy configuration (chaotic regime).
  state = [Math.PI * (0.5 + Math.random()), 0,
           Math.PI * (0.5 + Math.random()), 0];
  trail.length = 0;
});

window.addEventListener("resize", resize);
resize();
requestAnimationFrame(frame);
</script>
</body>
</html>
